openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}],"priceRange":"$$"},{"@type":"WebSite","@id":"https://newmexicoinsuranceappraiser.com/#website","url":"https://newmexicoinsuranceappraiser.com/","name":"New Mexico Insurance Appraiser","publisher":{"@id":"https://newmexicoinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://newmexicoinsuranceappraiser.com/claim-terms-a-to-z/#webpage","url":"https://newmexicoinsuranceappraiser.com/claim-terms-a-to-z/","name":"Insurance Claim Glossary | Searchable A to Z Terms","description":"A searchable insurance claim glossary: ACV, RCV, umpire, appraisal award, canales, parapets, percentage deductibles and dozens more terms.","inLanguage":"en-US","isPartOf":{"@id":"https://newmexicoinsuranceappraiser.com/#website"},"about":{"@id":"https://newmexicoinsuranceappraiser.com/#business"},"publisher":{"@id":"https://newmexicoinsuranceappraiser.com/#business"},"dateModified":"2026-11-13","primaryImageOfPage":{"@id":"https://newmexicoinsuranceappraiser.com/claim-terms-a-to-z/#primaryimage"},"breadcrumb":{"@id":"https://newmexicoinsuranceappraiser.com/claim-terms-a-to-z/#breadcrumb"},"mainEntity":{"@id":"https://newmexicoinsuranceappraiser.com/claim-terms-a-to-z/#definedtermset"}},{"@type":"ImageObject","@id":"https://newmexicoinsuranceappraiser.com/claim-terms-a-to-z/#primaryimage","url":"https://newmexicoinsuranceappraiser.com/assets/img/photos/hero-home-after-rain.webp","width":960,"height":640,"caption":"hero home after rain"},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://newmexicoinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Claim terms","item":"https://newmexicoinsuranceappraiser.com/claim-terms-a-to-z/"}],"@id":"https://newmexicoinsuranceappraiser.com/claim-terms-a-to-z/#breadcrumb"},{"@type":"DefinedTermSet","name":"Insurance claim terms A to Z","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual cash value (ACV)","description":"Replacement cost minus depreciation. Many policies pay ACV first and the balance after repairs are completed."},{"@type":"DefinedTerm","name":"Additional living expense (ALE)","description":"The extra cost of living elsewhere while a covered loss makes your home unlivable. It usually falls under Coverage D, loss of use."},{"@type":"DefinedTerm","name":"Adobe","description":"Sun-dried earthen block used in traditional New Mexico walls. Water and fire damage to adobe calls for specialized repair methods and pricing."},{"@type":"DefinedTerm","name":"Amount of loss","description":"The dollar value of the covered damage. It is the question an appraisal panel decides."},{"@type":"DefinedTerm","name":"Appraisal award","description":"The written decision signed by two of the three panel members that sets the amount of loss, ideally split into RCV, depreciation and ACV."},{"@type":"DefinedTerm","name":"Appraisal demand","description":"A written notice from you or the insurer invoking the policy’s appraisal clause because the parties disagree on the amount of loss."},{"@type":"DefinedTerm","name":"Canale","description":"A projecting channel or spout that drains water off a flat roof through a parapet wall. Hail and wind can crack or loosen canales."},{"@type":"DefinedTerm","name":"Competent and disinterested appraiser","description":"The standard most appraisal clauses set: someone qualified to value the loss who has no financial stake in the outcome."},{"@type":"DefinedTerm","name":"Coverage A (dwelling)","description":"The part of a homeowners policy that covers the house itself and attached structures."},{"@type":"DefinedTerm","name":"Coverage B (other structures)","description":"Coverage for detached structures such as garages, coyote fences, sheds and walls."},{"@type":"DefinedTerm","name":"Coverage C (personal property)","description":"Coverage for your belongings, often called contents, subject to sublimits for certain categories."},{"@type":"DefinedTerm","name":"Coverage D (loss of use)","description":"Coverage for additional living expense or lost rental income while the property can’t be used after a covered loss."},{"@type":"DefinedTerm","name":"Debris removal","description":"Coverage for hauling away damaged property and wreckage. After a wildfire it can be a major expense and may have its own limit."},{"@type":"DefinedTerm","name":"Declarations page","description":"The summary page of your policy showing limits, deductibles, the policy period and attached endorsements."},{"@type":"DefinedTerm","name":"Depreciation","description":"The reduction in value for age, wear and condition that separates replacement cost from actual cash value."},{"@type":"DefinedTerm","name":"Elastomeric roof coating","description":"A flexible liquid-applied coating used on many flat roofs. Hail can fracture or puncture it, exposing the membrane below."},{"@type":"DefinedTerm","name":"Endorsement","description":"A form that adds to, removes or changes coverage in the base policy."},{"@type":"DefinedTerm","name":"Evaporative cooler","description":"A rooftop or ground-mounted swamp cooler common across New Mexico. Hail dents cabinets, and the roof jack and curb can leak."},{"@type":"DefinedTerm","name":"Holdback","description":"The recoverable depreciation an insurer withholds until repairs or replacement are completed."},{"@type":"DefinedTerm","name":"Line item","description":"A single priced entry in an estimate, such as a square of membrane or a linear foot of parapet cap."},{"@type":"DefinedTerm","name":"Matching","description":"The question of whether undamaged materials must be replaced so repairs look uniform. Policy wording and New Mexico law both matter."},{"@type":"DefinedTerm","name":"Microburst","description":"A sudden, intense downdraft that produces damaging straight-line winds, often during monsoon storms."},{"@type":"DefinedTerm","name":"Mitigation","description":"Reasonable steps to prevent further damage after a loss, such as tarping a roof or drying out a wet room. Most policies require it."},{"@type":"DefinedTerm","name":"Modified bitumen","description":"An asphalt-based roll roofing membrane widely used on flat and low-slope roofs."},{"@type":"DefinedTerm","name":"Monsoon","description":"The summer storm season in New Mexico, roughly July through September, bringing hail, heavy rain, flash flooding and strong winds."},{"@type":"DefinedTerm","name":"New Mexico Property Insurance Program","description":"The state’s FAIR plan, a market of last resort for property owners who can’t buy coverage in the regular market."},{"@type":"DefinedTerm","name":"Office of Superintendent of Insurance (OSI)","description":"New Mexico’s insurance regulator. It licenses insurers and adjusters and takes consumer complaints."},{"@type":"DefinedTerm","name":"Ordinance or law coverage","description":"Coverage for added costs to bring repaired or rebuilt property up to current building codes, often subject to a percentage limit."},{"@type":"DefinedTerm","name":"Overhead and profit (O&P)","description":"The general contractor’s overhead and profit, commonly 10 percent each, often disputed when several trades are involved."},{"@type":"DefinedTerm","name":"Parapet","description":"The low wall extending above a flat roof, typical of Pueblo Revival and Territorial buildings. Its caps and flashing are frequent claim items."},{"@type":"DefinedTerm","name":"Percentage deductible","description":"A deductible figured as a percentage of the dwelling limit rather than a flat dollar amount, often applied to wind or hail."},{"@type":"DefinedTerm","name":"Pitch","description":"The slope of a roof, expressed as rise over 12 inches of run. Pitch affects area, labor and safety charges."},{"@type":"DefinedTerm","name":"Proof of loss","description":"A sworn statement of the amount claimed, which some policies require within a stated time after the insurer requests it."},{"@type":"DefinedTerm","name":"Recoverable depreciation","description":"Depreciation the insurer will pay once you complete repairs or replacement, under a replacement cost policy."},{"@type":"DefinedTerm","name":"Replacement cost value (RCV)","description":"The cost to repair or replace damaged property with materials of like kind and quality, without deduction for depreciation."},{"@type":"DefinedTerm","name":"Reservation of rights","description":"A letter in which the insurer handles a claim while reserving the right to deny coverage later."},{"@type":"DefinedTerm","name":"Scope of loss","description":"The list of damaged items and the repairs needed, before pricing. Many disputes are really scope disputes."},{"@type":"DefinedTerm","name":"Smoke damage","description":"Soot, odor and residue damage from fire. Wildfire smoke can affect a home that never burned, including HVAC systems and contents."},{"@type":"DefinedTerm","name":"Square (roofing)","description":"A unit of roof area equal to 100 square feet."},{"@type":"DefinedTerm","name":"Stucco","description":"A cement or synthetic exterior plaster finish common across New Mexico. Hail can fracture it, and matching texture and color is often disputed."},{"@type":"DefinedTerm","name":"Sublimit","description":"A lower limit inside a coverage for a specific category, such as jewelry, mold or debris removal."},{"@type":"DefinedTerm","name":"Suit limitation","description":"A policy provision that limits how long you have to sue the insurer. Check your policy and ask an attorney how New Mexico law treats it."},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third member of an appraisal panel who decides items the two appraisers can’t agree on."},{"@type":"DefinedTerm","name":"Waste factor","description":"An added percentage of material to cover cutting, overlap and fitting, especially on hip roofs and irregular layouts."},{"@type":"DefinedTerm","name":"Xactimate","description":"Estimating software used by most insurers and many contractors to price repairs line by line with regional pricing."}],"@id":"https://newmexicoinsuranceappraiser.com/claim-terms-a-to-z/#definedtermset"}]}</script>
</head>
